custom_css:
@import url("https://fontsapi.zeoseven.com/3/main/result.css");
@import url("https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;600&display=swap");

body {
  font-family: "Outfit", "寒蝉全圆体", sans-serif;
  font-weight: normal;
}


#chat > div.mes.smallSysMes.last_mes.fade {
    display: none !important;
}

#chat > div.welcomePanel > div.welcomeHeaderTitle > span {
    font-size: 10px !important;
}

* #send_form {
    border: none !important;
    outline: none !important;
}

#chat {
    border: none !important;
    overflow-y: auto !important;
    -webkit-overflow-scrolling: touch !important;
    padding-bottom: 120px !important;  
    box-sizing: border-box !important;
    overflow-x: hidden !important;
    outline: none !important;
}


#chat, #sheld, #form_create, .scrollableInner, #rm_api_block, .drawer-content, #rm_print_characters_block, #user-settings-block {
    overflow: auto;
    -ms-overflow-style: none;
    scrollbar-width: none;
}

#chat::-webkit-scrollbar, #sheld::-webkit-scrollbar, #form_create::-webkit-scrollbar, .scrollableInner::-webkit-scrollbar, #rm_api_block::-webkit-scrollbar, .drawer-content::-webkit-scrollbar, #rm_print_characters_block::-webkit-scrollbar, #user-settings-block::-webkit-scrollbar {
    display: none;
}

#sheld {
    overflow: hidden !important;
}


#form_sheld {
    position: absolute !important;
    bottom: 10px !important;
    left: 0 !important;
    width: 100% !important;
    z-index: 100 !important;
    background: transparent !important;
}

#form_sheld:has(#send_textarea:focus),
#form_sheld:has(#send_textarea:not(:placeholder-shown)) {
    position: static !important;
}

#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important;
}

#send_form {
    background: transparent !important;
    background-image: none !important;
    border: none !important;
    box-shadow: none !important;
}

#send_form::before {
    display: none !important;
}

#send_textarea {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
}


#send_but i, #send_but svg,
#options_button i, #options_button svg,
#extensionsMenuButton i, #extensionsMenuButton svg {
    display: none !important;
}


#options_button::before {
    content: '' !important;
    display: block !important;
    width: 15px !important;
    height: 15px !important;
    background-image: url('https://pic1.imgdb.cn/item/69b90c491eedde68249202f9.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
}

#extensionsMenuButton::before {
    content: '' !important;
    display: block !important;
    width: 15px !important;
    height: 15px !important;
    background-image: url('https://pic1.imgdb.cn/item/69b90c491eedde68249202f8.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
}

#send_but::before {
    content: '' !important;
    display: block !important;
    width: 20px !important;
    height: 20px !important;
    background-image: url('https://pic1.imgdb.cn/item/69b90c491eedde68249202f7.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
}

/* ===== 聊天气泡基础间距 ===== */
.mes[is_user="false"], .mes[is_user="true"] {
    margin-top: 100px !important;
    margin-bottom: 10px !important;
    padding: 0 !important;
    background: transparent !important;
}

.mes_text {
    padding-top: 20px !important;
    padding-bottom: 80px !important;
    padding-left: 10px !important;
    padding-right: 10px !important;
}


.character_select .avatar,
.character_select .avatar img {
    border-radius: var(--avatar-base-border-radius) !important;
    border: 1px solid var(--SmartThemeBorderColor) !important;
    box-shadow: 0 0 5px var(--black50a) !important;
    width: var(--avatar-base-width) !important;
    height: var(--avatar-base-height) !important;
    object-fit: cover !important;
    object-position: center !important;
}


.mes .avatar {
    width: 150px !important;
    height: 200px !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    overflow: visible !important;
}

.mes .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    object-position: center top !important;
    border: 3px solid rgba(255, 255, 255, 0.9) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
}


.mes[is_user="false"] .mesAvatarWrapper {
    position: absolute !important;
    top: -12px !important;
    right: 170px !important;
    left: auto !important;  
    width: 0px !important;
    height: 200px !important;
    z-index: 10 !important;
    overflow: visible !important;
}

/* AI：贴图 */
.mes[is_user="false"] .avatar::before {
    content: '' !important;
    display: block !important;
    position: absolute !important;
    top: -10px !important;
    right: -250px !important; 
    width: 400px !important;
    height: 300px !important;
    background-image: url('https://pic1.imgdb.cn/item/69b9115a1eedde68249211b3.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
    z-index: 10 !important;
}


.mes[is_user="false"] .mes_block {
    padding-top: 330px !important;
    background-color: #E8E3DF !important;
    box-shadow: 2px 6px 16px rgba(0, 0, 0, 0.18) !important;
    border-radius: 0px !important;
}


.mes[is_user="false"] .mes_block::before {
    content: '' !important;
    display: block !important;
    position: absolute !important;
    top: 100px !important;
    left: 0px !important;
    width: 100% !important;
    height: clamp(170px, 52vw, 230px) !important;
    background-image: url('https://pic1.imgdb.cn/item/69b9115a1eedde68249211b4.png') !important;
    background-size: 100% 100% !important;
    background-position: top left !important;
    pointer-events: none !important;
    z-index: 1 !important;
}


.mes[is_user="true"] .mesAvatarWrapper {
    position: absolute !important;
    top: -10px !important;
    left: 20px !important; 
    right: auto !important;
    width: 0px !important;
    height: 200px !important;
    z-index: 10 !important;
    overflow: visible !important;
}


.mes[is_user="true"] .avatar::before {
    content: '' !important;
    display: block !important;
    position: absolute !important;
    top: -15px !important;
    left: -35px !important; 
    width: 230px !important;
    height: 230px !important;
    background-image: url('https://pic1.imgdb.cn/item/69b91a171eedde6824925d56.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
    z-index: 10 !important;
}


.mes[is_user="true"] .mes_block {
    padding-top: 230px !important; 
    background-color: #D3C8B7 !important;
    box-shadow: 2px 6px 16px rgba(0, 0, 0, 0.18) !important;
    border-radius: 0px !important;
}


.mes, 
.mes_block {
    overflow: visible !important;
    position: relative !important;
}


#chat {
    overflow-x: visible !important;
    overflow-y: auto !important; 
}


.mes .mes_text {
    position: relative !important;
    z-index: 5 !important;
}



/* 用户火焰 */
.mes[is_user="true"] .mes_block::before {
    content: '' !important;
    position: absolute !important;
    top: -90px !important; 
    left: 0 !important;
    width: 100% !important;
    height: 240px !important;
    background-image: url('https://pic1.imgdb.cn/item/69b91fcf1eedde6824926983.png') !important;
    background-size: 100% 100% !important;
    background-repeat: no-repeat !important;
    z-index: 0 !important;
    pointer-events: none !important;
}

/* 用户底 */
.mes[is_user="true"] .mes_block::after {
    content: '' !important;
    position: absolute !important;
    bottom: -80px !important;
    left: 0 !important;
    width: 100% !important;
    height: 200px !important;
    background-image: url('https://pic1.imgdb.cn/item/69b91fcf1eedde6824926984.png') !important;
    background-size: 100% 100% !important;
    background-repeat: no-repeat !important;
    z-index: 0 !important;
    pointer-events: none !important;
}

/*AI火*/
.mes[is_user="false"] .mes_block::after {
    content: '' !important;
    position: absolute !important;
    left: 0px !important;
    width: clamp(200px, 95vw, 435px) !important;
    height: clamp(240px, 108vw, 580px) !important;
    top: calc(-1 * clamp(240px, 108vw, 500px) + 115px) !important;
    background-image: url('https://pic1.imgdb.cn/item/69b91fcf1eedde6824926982.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
    z-index: 5 !important;
}



.mes[is_user="false"] .mesAvatarWrapper::after {
    content: '' !important;
    position: absolute !important;
    bottom: -105px !important;   
    right: -200px !important;  
    width: 620px !important;
    height: 620px !important;
    background-image: url('https://pic1.imgdb.cn/item/69b9231d1eedde6824926a05.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
    z-index: 10 !important;
}



.mes[is_user="true"] .mesAvatarWrapper::after {
    content: '' !important;
    position: absolute !important;
    top: -40px !important;        
    left: -30px !important;     
    width: 180px !important;
    height: 180px !important;
    background-image: url('https://pic1.imgdb.cn/item/69b922ee1eedde6824926a01.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
    z-index: 10 !important;
}


/* AI 气泡底部中央*/
.mes[is_user="false"]::after {
    content: '' !important;
    position: absolute !important;
    bottom: -60px !important;     
    left: 50% !important;          
    transform: translateX(-50%) !important; 
    width: 420px !important;
    height: 200px !important;
    background-image: url('https://pic1.imgdb.cn/item/69b9259d1eedde6824926d22.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;
    z-index: -1 !important;        
}







.mes .flex-container.alignItemsBaseline {
    position: absolute !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: flex-start !important;
    gap: 4px !important;               
    z-index: 100 !important;
    pointer-events: none !important;   
}


.mes .name_text {
    font-size: 15px !important;
    color: #3B0808 !important;
    font-weight: 600 !important;
    line-height: 1.2 !important;
    order: 0 !important;                
}


.mes .flex-container.alignItemsBaseline::before {
    content: '' !important;
    display: block !important;
    width: 40% !important;
    height: 0.5px !important;
    background-color: #8B4513 !important; 
    margin: 2px 0 !important;
    order: 1 !important;                  
}


.mes .timestamp {
    font-size: 10px !important;
    color: #440F0F !important;
    font-weight: 400 !important;
    line-height: 1.2 !important;
    order: 2 !important;                  
    position: static !important;            
    transform: none !important;
}


.mes .flex-container.alignItemsBaseline::after {
    content: "I felt as if I were in spring, \A with your presence once close to me." !important;
    white-space: pre-wrap !important;      
    font-size: 10px !important;
    font-weight: 300 !important;           
    font-family: "Outfit", sans-serif !important;
    color: #440F0F !important;
    margin-top: 0px !important;
    order: 3 !important;
}


.mes[is_user="false"] .flex-container.alignItemsBaseline {
    top: 15px !important;          
    right: clamp(160px, 49vw, 220px) !important;
}


.mes[is_user="true"] .flex-container.alignItemsBaseline {
    top: 113px !important;
    left: 200px !important;          
    right: auto !important;

}


/*思维链*/
div.mes_reasoning_header.flex-container > * {
    visibility: hidden !important;  
}


.mes_reasoning_summary {
    position: relative !important;
    min-height: 40px !important;
}

div.mes_reasoning_header.flex-container {
    position: absolute !important;  
    right: 88% !important;         
    top: 20px !important;
    width: 180px !important;
    height: 40px !important;
    background: transparent !important;
    border: none !important;
    padding: 0px !important;
    margin: 0 !important;           
    overflow: visible !important;
    cursor: pointer !important;
}

div.mes_reasoning_header.flex-container > * {
    visibility: hidden !important;
}

div.mes_reasoning_header.flex-container::before {
    content: '' !important;
    position: absolute !important;
    top: 0 !important;
    left: 20% !important;
    width: 100% !important;
    height: 100% !important;
    background-image: url(https://pic1.imgdb.cn/item/69b932531eedde6824929855.png) !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
}




.mes_button.mes_edit i,
.mes_button.mes_edit svg,
.mes_button.extraMesButtonsHint i,
.mes_button.extraMesButtonsHint svg {
    display: none !important;
}


.mes_button.mes_edit,
.mes_button.extraMesButtonsHint {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    filter: none !important;             
    -webkit-filter: none !important;
    padding: 0 !important;
    width: 34px !important;
    height: 40px !important;
    flex-shrink: 0 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    cursor: pointer !important;
    transition: opacity 0.2s ease !important;
    position: relative !important;         
}


.mes_button.mes_edit::before,
.mes_button.extraMesButtonsHint::before {
    content: '' !important;
    display: block !important;
    width: 34px !important;
    height: 34px !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    pointer-events: none !important;       
}


.mes[is_user="true"] .mes_button.mes_edit::before {
    background-image: url('https://pic1.imgdb.cn/item/69b9360c1eedde682492c4f7.png') !important;
}

.mes[is_user="true"] .mes_button.extraMesButtonsHint::before {
    background-image: url('https://pic1.imgdb.cn/item/69b9360c1eedde682492c4f6.png') !important;
}

.mes[is_user="false"] .mes_button.mes_edit::before {
    background-image: url('https://pic1.imgdb.cn/item/69b9360c1eedde682492c4f7.png') !important;
}

.mes[is_user="false"] .mes_button.extraMesButtonsHint::before {
    background-image: url('https://pic1.imgdb.cn/item/69b9360c1eedde682492c4f6.png') !important;
}





.mes_buttons,
.mes .mesAvatarWrapper,
.mes_block {
    overflow: visible !important;
}

#chat {
    overflow-x: hidden !important;
    overflow-y: auto !important;
}


.mes_button.mes_edit,
.mes_button.extraMesButtonsHint {
    opacity: 1 !important;
}

.mes_button.mes_edit {
    transform: translate(-9px, 3px) !important;
}


.mes_button.extraMesButtonsHint {
    transform: translate(-15px, 3px) !important;
}


#curEditTextarea {
    background-color: #FDF5E6 !important;  
    box-shadow: inset 0 4px 8px rgba(0, 0, 0, 0.15) !important; 
    border: 1px solid #E0C9A6 !important;  
    color: #5C4B3A !important;             
}



.mes[is_user="false"] .mes_block,
.mes[is_user="true"] .mes_block {
    padding-left: 0 !important;
    padding-right: 0 !important;
}


#chat {
    padding-left: 8px !important;
    padding-right: 8px !important;
}


.mes {
    padding-left: 10px !important;
    padding-right: 10px !important;
}




.mes_text {
    padding-left: 10px !important;
    padding-right: 10px !important;

}


.swipe_left,
.swipe_right {
    font-size: 0 !important;
    color: transparent !important;
}
.swipe_left i,
.swipe_right i,
.swipe_left svg,
.swipe_right svg {
    display: none !important;
}


.swipe_left,
.swipe_right {
    background-image: none !important;   
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
    width: 20px !important;             
    height: 20px !important;
    cursor: pointer !important;
}


.swipe_left {
    position: absolute !important;
    left: 15px !important;             
    bottom: 15px !important;
    top: auto !important;
    right: auto !important;
}

.swipeRightBlock {
    position: absolute !important;
    right: 10px !important;              
    bottom: 10px !important;
