}


.swipes-counter {
    font-size: 10px !important;            
}


.swipe_left::before,
.swipe_right::before {
    content: '' !important;
    display: block !important;
    width: 100% !important;
    height: 100% !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    position: absolute !important;

}


.swipe_left::before {
    background-image: url('https://pic1.imgdb.cn/item/69b93a131eedde682492c51a.png') !important;
}


.swipe_right::before {
    background-image: url('https://pic1.imgdb.cn/item/69b93a131eedde682492c51b.png') !important;
}


.mes[is_user="false"] .tokenCounterDisplay,
.mes[is_user="false"] .mesIDDisplay,
.mes[is_user="false"] .mes_timer {
    color: #8B0000 !important;
}
.mes[is_user="true"] .tokenCounterDisplay,
.mes[is_user="true"] .mesIDDisplay {
    color: #FFFFFF !important;
}


.mes[is_user="false"] .tokenCounterDisplay {
    display: none !important;
}




.mes[is_user="true"] .mesIDDisplay {
    position: absolute !important;
    top: 60px !important;       
    left: 220px !important;     
    z-index: 20 !important;
}

.mes[is_user="true"] .tokenCounterDisplay {
    position: absolute !important;
    top: 75px !important;      
    left: 220px !important;     
    z-index: 20 !important;
}

.mes[is_user="false"] .tokenCounterDisplay {
    display: block !important;
    position: absolute !important;
   top: clamp(270px, 68vw, 310px) !important;
    right: clamp(40px, 12vw, 70px) !important;
    z-index: 20 !important;
}

.mes[is_user="false"] .mes_timer {
    position: absolute !important;
    top: clamp(258px, 65vw, 295px) !important;   
    right: clamp(40px, 12vw, 70px) !important;
    z-index: 20 !important;
}

.mes[is_user="true"] .mesIDDisplay,
.mes[is_user="true"] .tokenCounterDisplay,
.mes[is_user="false"] .tokenCounterDisplay,
.mes[is_user="false"] .mes_timer {
    font-size: 11px !important;      
    font-weight: 700 !important;     
    font-family: "Outfit", sans-serif !important;  
}


#chat {

    -webkit-mask: linear-gradient(
        to bottom,
        transparent 0%,
        rgba(0, 0, 0, 0.1) 3%,
        rgba(0, 0, 0, 0.6) 6%,
        black 15%,
        black 85%,
        rgba(0, 0, 0, 0.6) 92%,
        rgba(0, 0, 0, 0.1) 97%,
        transparent 100%
    ) !important;
}



#top-bar {
    transform: scaleY(0);
    transform-origin: top;
    background-color: transparent;
}


#top-settings-holder {
    position: relative !important;
    height: 27px !important;
    overflow: visible !important;
    flex-wrap: nowrap !important;
    align-items: flex-start !important;
}


