    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
    border: 1px solid rgba(180, 150, 120, 0.28) !important;
    box-shadow: 0 6px 24px rgba(80, 40, 20, 0.08) !important;
