    box-shadow: none !important;
    font-size: 13px !important;
    font-weight: 600 !important;
    letter-spacing: 0.08em !important;
}


.drawer-content select,
.drawer-content input[type="text"],
.drawer-content input[type="number"],
.drawer-content textarea,
#character_search_bar,
#persona_search_bar {
    background: rgba(240, 230, 218, 0.35) !important;
    border: 1px solid rgba(180, 150, 120, 0.35) !important;
    box-shadow: none !important;
    color: #3B0808 !important;
